CREATE DATABASE IF NOT EXISTS `moja_strona` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;CREATE TABLE `moja_strona`.`page_list` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT , `alias` VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL , `page_title` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL , `page_content` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL , `status` TINYINT UNSIGNED NOT NULL DEFAULT '1' , PRIMARY KEY (`id`), UNIQUE (`alias`)) ENGINE = InnoDB;
